| on_state_control_changed | Trigger the following commands when a state's controller changes. | *(example below)* | ROOT is new controller, FROM is old controller, FROM.FROM is state ID. | 1.4 |

**Example: on_state_control_changed**

```text
on_state_control_changed = {
    effect = {
        if = {
            limit = {
                FROM.FROM = { state = 123 }
            }
            if =  {
                limit = {
                    tag = BHR
                }

custom_effect_tooltip = AST_dividing_the_pacific_ast_gain_tt 	
#If MAL/Singapore/SIA isn't controlled by JAP or AST, add AST state claims
MAL = {
	every_core_state = {
		limit = { 
			NOT = {
				is_controlled_by = AST
				is_controlled_by = JAP				
			}
		}
	set_state_flag = AST_claims_to_ast
	add_claim_by = AST 
	}
}

        OR = {
            BRM = { 
            	OR = {
            		is_subject_of = AST 
            		has_country_flag = AST_brm_puppet_to_jap
            	}
            }
            any_state = {
                is_core_of = BRM
                OR = {
	                is_controlled_by = AST
	                has_state_flag = AST_transfer_to_jap
